1	/**
2	 * Guards the contract between `linear:plan`, which stores an implementation plan in a
3	 * Linear issue's description, and `linear:run`, which executes a valid stored plan
4	 * verbatim or falls back to a run-local fresh plan when the artifact is unusable.
5	 *
6	 * Five properties are load-bearing, and each fails silently without a guard:
7	 *
8	 * 1. The stored-plan section names `linear:run` reads match the ones `linear:plan` writes.
9	 *    This is the real rot: the two files have no import between them, so renaming a
10	 *    section in the producer breaks the consumer with nothing failing in between.
11	 * 2. `linear:run` enumerates every validation verdict and maps it to an execution mode.
12	 *    A verdict quietly dropped can turn an unusable artifact into executable instructions.
13	 * 3. `linear:run` never dispatches `linear:plan` or rewrites the ticket. Its fresh-plan
14	 *    path must remain a run-local fallback rather than silently replacing the artifact.
15	 * 4. The two skills agree on the stored format version. `Format:` is the only thing that
16	 *    keeps "written under an older template" apart from "corrupt", and a version the
17	 *    producer writes but the consumer does not read collapses that distinction.
18	 * 5. One scoring threshold governs every caller. The threshold is read out of
19	 *    `pipeline.md` rather than asserted as a literal, so tuning it stays a one-file
20	 *    change — but a caller that restates it must restate the same number.
21	 *
22	 * The section names and the threshold are extracted from the producer's own text rather
23	 * than hardcoded, so the guard tracks the source instead of a copy of it.
24	 *
25	 * What this CANNOT prove: that the gate runs, or that the model honours it. CI sees text
26	 * in a file, nothing more — the same limit `sharedRulesInvocation.test.ts` states for its
27	 * own presence checks. Worse here, no workflow executes this test at all (nothing under
28	 * `.github/workflows/` runs `bun test`), so it gates locally and in review, not in CI.
29	 * Runtime evidence comes from the dry-run recorded on the PR.
30	 */
31	import { readFile } from "node:fs/promises";
32	import { join } from "node:path";
33	
34	import { describe, expect, test } from "bun:test";
35	
36	const actionDir = join(import.meta.dirname, "..");
37	const repoRoot = join(actionDir, "..", "..", "..");
38	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
39	
40	const readSkill = (name: string): Promise<string> =>
41	  readFile(join(skillsDir, name, "SKILL.md"), "utf8");
42	
43	const [linearPlan, linearRun, plan, run, runPrimed, pipeline] = await Promise.all([
44	  readSkill("linear:plan"),
45	  readSkill("linear:run"),
46	  readSkill("plan"),
47	  readSkill("run"),
48	  readSkill("run-primed"),
49	  readFile(join(skillsDir, "plan/references/pipeline.md"), "utf8"),
50	]);
51	
52	/** Every verdict `linear:run`'s validation table must name, fallback ones first. */
53	const fallbackVerdicts = ["missing", "version-mismatch", "malformed", "unverifiable"];
54	const allVerdicts = [...fallbackVerdicts, "valid"];
55	
56	/**
57	 * `### <name>` rows of the stored-plan template in `linear:plan`, split by its own
58	 * required/caller-owned marker. Reading the producer's template is what makes a renamed
59	 * section fail here rather than at runtime against a live ticket.
60	 */
61	function storedSections(source: string, kind: "required" | "caller-owned"): string[] {
62	  const rows = source.matchAll(/^###\s+(.+?)\s+<-\s+(required|caller-owned)$/gm);
63	  return [...rows].filter((row) => row[2] === kind).map((row) => row[1].trim());
64	}
65	
66	const requiredSections = storedSections(linearPlan, "required");
67	const callerOwnedSections = storedSections(linearPlan, "caller-owned");
68	
69	/** The `Source | Section` table rows in `linear:run`, keyed by the source cell. */
70	function sectionTableRow(source: string, key: string): string {
71	  const row = source
72	    .split("\n")
73	    .map((line) => line.split("|").map((cell) => cell.trim()))
74	    .find((cells) => cells.length > 2 && cells[1] === key);
75	  return row ? row[2] : "";
76	}
77	
78	/** The scoring threshold the shared pipeline states, e.g. `98` from `Scoring target: 98+`. */
79	const threshold = pipeline.match(/Scoring target:\s*(\d+)\+/)?.[1] ?? "";
80	
81	/** The revision budget the shared pipeline states, e.g. `three` from `at most three passes`. */
82	const passBudget = pipeline.match(/at most (\w+) passes/)?.[1] ?? "";
83	
84	describe("linear plan contract", () => {
85	  test("the stored-plan template still exposes a required/caller-owned split", () => {
86	    expect(requiredSections.length).toBeGreaterThan(1);
87	    expect(callerOwnedSections.length).toBeGreaterThan(0);
88	  });
89	
90	  test.each(allVerdicts)("linear:run names the %s verdict", (verdict) => {
91	    expect(linearRun).toContain(`**${verdict}**`);
92	  });
93	
94	  test.each(fallbackVerdicts)("the %s verdict selects a fresh plan", (verdict) => {
95	    const message = linearRun.split("\n").find((line) => line.startsWith(`- ${verdict} —`));
96	    expect(`${verdict}: ${message ?? "<no message line>"}`).toContain(
97	      "drafting a fresh implementation plan",
98	    );
99	  });
100	
101	  test("the verdict table maps valid to stored-plan and every other verdict to fresh-plan", () => {
102	    const validRow = linearRun
103	      .split("\n")
104	      .find((line) => line.includes("| **valid**") && line.includes("`stored-plan`"));
105	    const fallbackRow = linearRun
106	      .split("\n")
107	      .find(
108	        (line) =>
109	          line.includes("`fresh-plan`") &&
110	          fallbackVerdicts.every((verdict) => line.includes(`**${verdict}**`)),
111	      );
112	    expect(validRow).toContain("`stored-plan`");
113	    expect(fallbackRow).toContain("`fresh-plan`");
114	  });
115	
116	  test("linear:run never invokes the producer or overwrites the stored artifact", () => {
117	    expect(linearRun).not.toContain("Skill(autopilot:linear-plan)");
118	    expect(linearRun).toContain("never writes or repairs a stored plan");
119	    expect(linearRun).toContain("Do not store it on the Linear issue");
120	  });
121	
122	  test.each([
123	    ["admission", "Only the Linear issue is required"],
124	    ["snapshot", "The plan is a snapshot, not a live view"],
125	  ])("linear:run states the %s contract", (_label, needle) => {
126	    expect(linearRun).toContain(needle);
127	  });
128	
129	  test("linear:run uses the shared planning pipeline for its fresh-plan path", () => {
130	    expect(linearRun).toContain("[pipeline.md](../plan/references/pipeline.md)");
131	    expect(linearRun).toContain('task 4 ("Establish plan")');
132	    expect(linearRun).toContain('task 5 ("Validate plan")');
133	    expect(linearRun).toContain('task 6 ("Finalize plan")');
134	  });
135	
136	  test.each(requiredSections)("linear:run consumes `### %s` from the stored plan", (name) => {
137	    expect(sectionTableRow(linearRun, "Stored plan")).toContain(`\`### ${name}\``);
138	  });
139	
140	  test.each(callerOwnedSections)("`### %s` is stored but explicitly not consumed", (name) => {
141	    expect(sectionTableRow(linearRun, "Stored plan, **unused**")).toContain(`\`### ${name}\``);
142	    expect(sectionTableRow(linearRun, "Stored plan")).not.toContain(`\`### ${name}\``);
143	  });
144	
145	  test("both skills agree on the stored format version", () => {
146	    const written = linearPlan.match(/Format:\s*(v\d+)/)?.[1];
147	    expect(written).toBeTruthy();
148	    expect(linearRun).toContain(`\`${written}\``);
149	  });
150	
151	  test("the shared pipeline states one threshold and one revision budget", () => {
152	    expect(threshold).not.toBe("");
153	    expect(passBudget).not.toBe("");
154	    for (const rule of ["is below", "still scores below"]) {
155	      const line = pipeline.split("\n").find((l) => l.includes(rule));
156	      expect(`${rule}: ${line ?? "<absent>"}`).toContain(threshold);
157	    }
158	  });
159	
160	  test("linear:plan restates the pipeline's threshold and budget, not its own", () => {
161	    expect(linearPlan).toContain(`${threshold} or above`);
162	    expect(linearPlan).toContain(`Below ${threshold}`);
163	    expect(linearPlan).toContain(`${passBudget}-pass`);
164	  });
165	
166	  test("the pipeline reconciles below-threshold behaviour per caller", () => {
167	    const [, belowThreshold = ""] = pipeline.split("Report honestly");
168	    for (const caller of ["`plan`", "`run`", "`run-primed`", "`linear:run`", "`linear:plan`"]) {
169	      expect(belowThreshold).toContain(caller);
170	    }
171	  });
172	
173	  test("linear:plan refuses to store below the threshold without discarding the plan", () => {
174	    expect(linearPlan).toContain("emit the full plan text into the transcript");
175	  });
176	
177	  test("linear:plan stores eligible plans without a separate human approval step", () => {
178	    expect(linearPlan).toContain("Do not add a separate approval step");
179	    expect(linearPlan).not.toContain("## Phase 4: Request approval");
180	    expect(linearPlan).not.toContain("The human approves the plan before it is stored");
181	  });
182	
183	  test("linear:run treats the stored plan as a durable artifact, not proof of approval", () => {
184	    expect(linearRun).toContain("checkable durable artifact");
185	    expect(linearRun).not.toContain("approval already happened when the plan was stored");
186	    expect(linearRun).not.toContain("plan somebody approved");
187	  });
188	
189	  test.each([
190	    ["revision", "Stored plan was drafted against"],
191	    ["path", "path(s) that no longer exist"],
192	  ])("linear:run reports %s drift", (_label, needle) => {
193	    expect(linearRun).toContain(needle);
194	  });
195	
196	  test("both drift reports stay advisory rather than becoming verdicts", () => {
197	    const [, drift = ""] = linearRun.split("report how far the plan has aged");
198	    expect(drift).toContain("advisory and never a verdict");
199	    // A drift report must not be smuggled in as a sixth plan-source verdict.
200	    for (const verdict of fallbackVerdicts) {
201	      expect(`drift section names ${verdict}: ${drift.includes(`**${verdict}**`)}`).toBe(
202	        `drift section names ${verdict}: false`,
203	      );
204	    }
205	  });
206	
207	  /**
208	   * Both carve-outs guard the same failure: the plan template stores an existing file as
209	   * `path/to/file.ts:NN` and a planned one with a `(new)` suffix, so a literal existence
210	   * test on the raw entry reports every file as missing — the cry-wolf outcome that would
211	   * make the report worthless.
212	   */
213	  test.each([
214	    ["files it intends to create", "absent by design"],
215	    ["a trailing line number", "Strip a trailing"],
216	  ])("the path check handles %s", (_label, needle) => {
217	    const [, drift = ""] = linearRun.split("**Path drift.**");
218	    expect(drift).toContain(needle);
219	  });
220	
221	  test("the unchanged callers state no threshold of their own", () => {
222	    for (const [name, source] of [
223	      ["plan", plan],
224	      ["run", run],
225	      ["run-primed", runPrimed],
226	    ] as const) {
227	      expect(`${name}: ${source.includes("Scoring target")}`).toBe(`${name}: false`);
228	    }
229	  });
230	
231	  test("ordinary plan and run know nothing of the stored plan", () => {
232	    for (const [name, source] of [
233	      ["plan", plan],
234	      ["run", run],
235	      ["run-primed", runPrimed],
236	    ] as const) {
237	      expect(`${name}: ${source.includes("## Implementation plan")}`).toBe(`${name}: false`);
238	    }
239	  });
240	});
