1	/**
2	 * Guards the audience split between the plan file and the skills that write it: a plan
3	 * file is what a human approves, so the text copied into it describes outcomes in prose
4	 * and never carries the tool calls that produce them. Those live in the phase that runs
5	 * them — see the "Plan file is output, not instructions" rule in plan/SKILL.md.
6	 *
7	 * The insert bodies are exactly the fenced blocks whose first heading is `## Pre-Implementation`
8	 * or `## Post-Implementation`: branch-blocks.md keys one per input type, pipeline.md's draft
9	 * template carries the default tail, and run/SKILL.md substitutes its automated variant. This
10	 * finds them by walking the tree rather than naming those three files, the same load-bearing
11	 * property linkResolution.test.ts and sharedRulesInvocation.test.ts rely on — a fourth insert
12	 * body added anywhere under skills/ is covered without editing this test.
13	 *
14	 * What this CANNOT prove: that an emitted plan file is clean. CI sees the template, not the
15	 * artifact; a drafter can still hand-write a tool call into a plan. Runtime evidence comes from
16	 * inspecting a plan file written by a real run, recorded on the PR.
17	 */
18	import { readFile } from "node:fs/promises";
19	import { join, relative } from "node:path";
20	
21	import { describe, expect, test } from "bun:test";
22	
23	import { walkMarkdown } from "./markdownFiles";
24	
25	const actionDir = join(import.meta.dirname, "..");
26	const repoRoot = join(actionDir, "..", "..", "..");
27	const skillsDir = join(repoRoot, "claude-plugins/autopilot/skills");
28	
29	/**
30	 * Agent-facing constructs that must never reach a plan file. Each is matched as a literal
31	 * substring, so a partial leftover fails too — a body that keeps only the `options` array
32	 * still trips `Tool parameters`.
33	 */
34	const forbidden = [
35	  { token: "Skill(", why: "a skill dispatch belongs to the phase that runs it" },
36	  { token: "Tool parameters", why: "an AskUserQuestion parameter block is not prose" },
37	  { token: "AskUserQuestion", why: "naming the tool describes the mechanism, not the outcome" },
38	  { token: "<!--", why: "an HTML-comment directive addresses the agent, not the reader" },
39	];
40	
41	const insertBodyHeadings = ["## Pre-Implementation", "## Post-Implementation"];
42	
43	interface InsertBody {
44	  /** Repo-relative file the body lives in. */
45	  file: string;
46	  /** 1-indexed line the opening fence sits on, so a failure points at the source. */
47	  line: number;
48	  heading: string;
49	  content: string;
50	}
51	
52	/**
53	 * Fenced blocks carrying an insert-body heading anywhere inside them. It has to be anywhere
54	 * rather than on the first heading line: branch-blocks.md fences a lone section, while
55	 * pipeline.md fences the whole plan-file template, where `## Post-Implementation` sits below
56	 * `## Summary`. Either way the entire fence is text destined for a plan file, so the whole
57	 * block is checked. Honours CommonMark fences of any length so a longer outer fence does not
58	 * terminate early.
59	 */
60	function insertBodies(file: string, source: string): InsertBody[] {
61	  const out: InsertBody[] = [];
62	  const lines = source.split("\n");
63	  let open: { len: number; char: string; start: number } | null = null;
64	  let body: string[] = [];
65	
66	  for (const [index, line] of lines.entries()) {
67	    const fence = /^(`{3,}|~{3,})/.exec(line.trimStart());
68	    if (!open) {
69	      // Ternary rather than a nested `if`: block nesting is capped at 2 (CLAUDE.md).
70	      open = fence ? { len: fence[1].length, char: fence[1][0], start: index } : null;
71	      continue;
72	    }
73	    const closes =
74	      fence && fence[1][0] === open.char && fence[1].length >= open.len;
75	    if (!closes) {
76	      body.push(line);
77	      continue;
78	    }
79	    const heading = body
80	      .map((l) => l.trim())
81	      .find((l) => insertBodyHeadings.some((h) => l.startsWith(h)));
82	    if (heading) {
83	      out.push({ file, line: open.start + 1, heading, content: body.join("\n") });
84	    }
85	    open = null;
86	    body = [];
87	  }
88	  return out;
89	}
90	
91	const files = await walkMarkdown(skillsDir);
92	const bodies = (
93	  await Promise.all(
94	    files.map(async (file) =>
95	      insertBodies(relative(repoRoot, file), await readFile(file, "utf8")),
96	    ),
97	  )
98	).flat();
99	
100	describe("plan file output purity", () => {
101	  test("insert bodies are discovered, not hardcoded", () => {
102	    // branch-blocks.md keys four by input type; pipeline.md and run/SKILL.md add one each.
103	    expect(bodies.length).toBeGreaterThanOrEqual(6);
104	    expect(new Set(bodies.map((b) => b.file)).size).toBeGreaterThanOrEqual(3);
105	  });
106	
107	  test.each(bodies.map((b) => [`${b.file}:${b.line} ${b.heading}`, b] as const))(
108	    "%s carries no agent-facing tool call",
109	    (label, b) => {
